cd /dateutil && python - <<'EOF'
import re, collections
before = open('/tmp/before.txt').read().splitlines()
after = open('/tmp/after.txt').read().splitlines()
assert len(before) == len(after)
cats = collections.Counter()
examples = collections.defaultdict(list)
for b, a in zip(before, after):
    if b == a:
        continue
    def kind(line):
        if '-> datetime' in line:
            return 'datetime'
        if '-> (' in line:
            return 'tuple'
        m = re.search(r'-> (\w+Error): (.*)$', line)
        if m:
            return '%s: %s' % (m.group(1), m.group(2))
        return line
    key = (kind(b), kind(a))
    cats[key] += 1
    if len(examples[key]) < 3:
        examples[key].append((b, a))
for k, v in cats.most_common():
    print(v, k)
    for b, a in examples[k]:
        print('   B', b[:140])
        print('   A', a[:140])
EOF

cd /dateutil && python - <<'EOF'
import re, collections
before = open('/tmp/before2.txt').read().splitlines()
after = open('/tmp/after2.txt').read().splitlines()
def kind(line):
    if '-> datetime' in line:
        return 'OK-datetime'
    if '-> (' in line:
        return 'OK-tuple'
    m = re.search(r'-> (\w+Error): (.*)$', line)
    if m:
        return 'ERR %s: %s' % (m.group(1), m.group(2))
    return line
cats = collections.Counter()
regressions = []
for b, a in zip(before, after):
    if b == a:
        continue
    kb, ka = kind(b), kind(a)
    cats[(kb, ka)] += 1
    if kb.startswith('OK') and ka.startswith('ERR'):
        regressions.append((b, a))
for k, v in cats.most_common():
    print(v, k)
print('REGRESSIONS:', len(regressions))
for b, a in regressions[:10]:
    print(' B', b[:120]); print(' A', a[:120])
EOF
